#include <iostream>

struct Node { int value; const Node* left; const Node* right; };
int sum(const Node* node) {
    if (!node) return 0;
    return node->value + sum(node->left) + sum(node->right);
}
int main() {
    const Node left{2, nullptr, nullptr}, right{3, nullptr, nullptr};
    const Node root{1, &left, &right};
    std::cout << sum(&root) << '\n';
}
